import threading

def find_prime(n, greater_than):
    count = 0
    number = greater_than + 1
    while count < n:
        for i in range(2, number):
            if number % i == 0:
                break
        else:
            print(f"Prime number #{count + 1} after {greater_than}: {number}")
            count += 1
        number += 1

def multithreaded_processing(inputs):
    threads = [threading.Thread(target=find_prime, args=(n, num)) for n, num in inputs]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

if __name__ == '__main__':
    inputs = [(5, 10), (3, 20), (4, 30)]
    multithreaded_processing(inputs)
```

