        if char not in letters:
            letters[char] = 1
        else:
            letters[char] += 1

    # Identify how many letters have an odd count
    odd_count = sum(1 for count in letters.values() if count % 2 != 0)

    # If more than one letter has an odd count, the shortest palindrome possible is the length
    # of the word plus the count of letters with odd count minus one.
    if odd_count > 1:
        return len(word) + odd_count - 1
    # If one or zero letters have an odd count, the shortest palindrome is the length of the word.
    else:
