def findLongestWord(s, dictionary):
    def is_subsequence(s, t):
        iter_t = iter(t)
        return all(c in iter_t for c in s)

    def no_consecutive_chars(s):
        for i in range(len(s)-1):
            if s[i] == s[i+1]:
                return False
        return True

    dictionary.sort(key=lambda x: (-len(x), x))  # sort by length descending, then lexicographically
    for word in dictionary:
        if is_subsequence(word, s) and no_consecutive_chars(word):
            return word
    return ""
