```python
import re

def is_palindrome(s):
    return s == s[::-1]

def has_palindrome_substring(word, length=3):
    for i in range(len(word) - length + 1):
        if is_palindrome(word[i:i+length]):
            return True
    return False

def match_words(words):
    matched_words = []
    for word in words:
        if not re.match('^[a-z]*$', word):
            continue
        if has_palindrome_substring(word):
            matched_words.append(word)
    return matched_words

words = ["hello", "mom", "world", "dad", "pythonyhtyp", "python", "anaconda", "anacna", "qwertyytrewq"]
print(match_words(words))
```
