def minOperations(n: int) -> int:
    dp = [0, 0, 1, 2] + [0] * (n - 3)
    for i in range(4, n + 1):
        if i % 2 == 0:
            dp[i] = min(dp[i // 2], dp[i - 1] + 1) + 1
